package net.officefloor.hq.app;

import java.util.List;

/**
 * What the API exposes for a project: the shape the front-end renders into the projects table. The
 * cross-entity join lives here — the project carries its client's NAME (not just the id) so the list
 * can show the client without a second lookup, and the ids of the tags on it so the list can be
 * filtered by tag without a second lookup per row.
 */
public record ProjectView(Long id, String name, Long clientId, String clientName,
        boolean archived, String status, List<Long> tagIds) {

    public static ProjectView of(Project project, String clientName) {
        return of(project, clientName, List.of());
    }

    public static ProjectView of(Project project, String clientName, List<Long> tagIds) {
        return new ProjectView(project.getId(), project.getName(), project.getClientId(),
                clientName, project.isArchived(), project.getStatus(), tagIds);
    }
}
package net.officefloor.hq.app;

/**
 * Where a project sits in its lifecycle. A project is marked as one of these; the list and the
 * create form surface the chosen value. Stored by name on the {@code projects} table
 * (V22__project_status.sql).
 */
public enum ProjectStatus {
    ACTIVE,
    ON_HOLD,
    FINISHED;

    /** Parse a submitted status, falling back to {@link #ACTIVE} for a blank/unknown value. */
    public static ProjectStatus parse(String value) {
        if (value == null) {
            return ACTIVE;
        }
        for (ProjectStatus status : values()) {
            if (status.name().equals(value.trim())) {
                return status;
            }
        }
        return ACTIVE;
    }
}
package net.officefloor.hq.app;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.web.ObjectResponse;

/**
 * GET /api/projects — every project, in id order, each carrying its client's NAME so the list can
 * show the client without the front-end joining, and the ids of the tags on it so the list can be
 * filtered by tag. Wired by officefloor/rest/api/projects.GET.yml.
 */
public class ListProjects {

    public void service(ProjectRepository projects, ClientRepository clients,
            ProjectTagRepository projectTags, ObjectResponse<List<ProjectView>> response) {
        Map<Long, String> names = clients.findAll().stream()
                .collect(Collectors.toMap(Client::getId, Client::getName));
        // Which tag ids sit on each project — grouped once from the join so a list of any size is a
        // single scan, not a query per row.
        Map<Long, List<Long>> tagsByProject = projectTags.findAll().stream()
                .collect(Collectors.groupingBy(ProjectTag::getProjectId,
                        Collectors.mapping(ProjectTag::getTagId, Collectors.toList())));
        List<ProjectView> view = projects.findAll().stream()
                .sorted((a, b) -> Long.compare(a.getId(), b.getId()))
                .map(p -> ProjectView.of(p, names.getOrDefault(p.getClientId(), ""),
                        tagsByProject.getOrDefault(p.getId(), new ArrayList<>())))
                .toList();
        response.send(view);
    }
}
